public class Main {
    // One step per item -> O(n)
    static long linear(int n) {
        long steps = 0;
        for (int i = 0; i < n; i++) steps++;
        return steps;
    }
    // n steps for every item -> O(n^2)
    static long quadratic(int n) {
        long steps = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) steps++;
        return steps;
    }
    public static void main(String[] args) {
        // Doubling n doubles the linear count and multiplies the quadratic count by 4
        int[] sizes = {100, 200, 400};
        for (int n : sizes)
            System.out.println("n=" + n + " linear=" + linear(n) + " quadratic=" + quadratic(n));
        // Time: O(n) and O(n^2). Space: O(1).
    }
}

