public class Main {
    // Returns how many comparisons were needed to find target (or to give up)
    static int comparisons(int[] a, int target) {
        int count = 0;
        for (int x : a) {
            count++;                 // one comparison per element looked at
            if (x == target) break;  // found: stop early
        }
        return count;
    }
    public static void main(String[] args) {
        int[] a = {7, 3, 9, 4, 8, 1, 5, 2};
        System.out.println("array = [7, 3, 9, 4, 8, 1, 5, 2]");
        // Best case: the target is the first element -> Theta(1)
        System.out.println("search 7 (first):   " + comparisons(a, 7) + " comparisons");
        // Worst case: the target is last or missing -> Theta(n)
        System.out.println("search 2 (last):    " + comparisons(a, 2) + " comparisons");
        System.out.println("search 6 (missing): " + comparisons(a, 6) + " comparisons");
        // Time: O(n) and Omega(1) over all inputs. Space: O(1).
    }
}

