public class Main {
    public static void main(String[] args) {
        int[] sizes = {8, 1024};
        for (int n : sizes) {
            long tri = 0, harm = 0, geo = 0;
            // Inner loop runs i times: 0 + 1 + ... + (n-1) = n(n-1)/2 -> O(n^2)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < i; j++) tri++;
            // Inner loop jumps by i: n/1 + n/2 + ... + n/n -> O(n log n)
            for (int i = 1; i <= n; i++)
                for (int j = i; j <= n; j += i) harm++;
            // Work halves each round: n + n/2 + n/4 + ... < 2n -> O(n)
            for (int k = n; k >= 1; k /= 2)
                for (int j = 0; j < k; j++) geo++;
            System.out.println("n=" + n + " inner-runs-i=" + tri + " step-i=" + harm + " halving=" + geo);
        }
        // Space: O(1) for all three.
    }
}

