    // Count the halvings needed to bring n down to 1 (this is floor(log2 n))
    static int halvings(long n) {
        int steps = 0;
        while (n > 1) {
            n /= 2;      // throw away half of what is left
            steps++;
        }
        return steps;
    }
    public static void main(String[] args) {
        // Even a huge n needs only a handful of halvings
        long[] values = {8L, 1000L, 1000000000L, 1000000000000000000L};
        for (long n : values)
            System.out.println("n=" + n + " halvings=" + halvings(n));
        // Time: O(log n). Space: O(1).
    }
}

