import java.util.Arrays;
public class Main {
    public static void main(String[] args) {
        int[] a = {1, 2, 3, 4, 5, 6};
        System.out.println("input:    " + Arrays.toString(a));
        // Version 1: build a new array -> n extra cells, O(n) auxiliary space
        int[] copy = new int[a.length];
        for (int i = 0; i < a.length; i++) copy[i] = a[a.length - 1 - i];
        System.out.println("copy:     " + Arrays.toString(copy) + " extra cells = " + copy.length);
        // Version 2: swap the two ends and walk inwards -> O(1) auxiliary space
        int lo = 0, hi = a.length - 1;
        while (lo < hi) {
            int tmp = a[lo];          // the only extra memory: one temp value
            a[lo] = a[hi];
            a[hi] = tmp;
            lo++; hi--;
        }
        System.out.println("in place: " + Arrays.toString(a) + " extra cells = 1");
        // Time: O(n) for both. Space: O(n) vs O(1).
    }
}

