public class Main {
    public static void main(String[] args) {
        long n = 100000, limit = 100000000;   // about 10^8 simple operations per second
        long log = 0;                          // ceil(log2 n)
        while ((1L << log) < n) log++;
        long root = 0;                         // floor(sqrt n)
        while ((root + 1) * (root + 1) <= n) root++;
        String[] names = {"O(N)", "O(N log N)", "O(N sqrt N)", "O(N^2)"};
        long[] ops = {n, n * log, n * root, n * n};   // long: N^2 = 10^10 overflows int
        System.out.println("N=" + n + " log2=" + log + " sqrt=" + root + " budget=" + limit);
        for (int i = 0; i < names.length; i++) {
            // A plan is safe when its operation count stays under the budget
            String verdict = ops[i] <= limit ? "fits" : "too slow";
            System.out.println(names[i] + " -> " + ops[i] + " operations: " + verdict);
        }
        // Time: O(log n + sqrt n) for this estimate. Space: O(1).
    }
}

