public class Main {
    // Simulate n appends and count how many elements get copied during resizes
    static long copies(int n, boolean doubling) {
        long copied = 0;
        int capacity = doubling ? 1 : 10, size = 0;
        for (int i = 0; i < n; i++) {
            if (size == capacity) {            // full: move everything to a bigger block
                copied += size;
                capacity = doubling ? capacity * 2 : capacity + 10;
            }
            size++;
        }
        return copied;
    }
    public static void main(String[] args) {
        int[] sizes = {1000, 2000, 4000};
        for (int n : sizes) {
            // Doubling: copies stay below 2n. Plus-10: copies grow like n^2 / 20.
            System.out.println("appends=" + n + " doubling copies=" + copies(n, true)
                + " plus-10 copies=" + copies(n, false));
        }
        // Doubling: O(1) amortised per append. Plus-10: O(n) amortised. Space: O(n).
    }
}

