public class Main {
    // Bottom-up build: sift every non-leaf node down, starting from the last one
    static long buildBottomUp(int[] h, int n) {
        long swaps = 0;
        for (int start = n / 2 - 1; start >= 0; start--) {
            int i = start;
            while (true) {
                int big = i, l = 2 * i + 1, r = 2 * i + 2;
                if (l < n && h[l] > h[big]) big = l;
                if (r < n && h[r] > h[big]) big = r;
                if (big == i) break;           // a node moves down at most its height
                int t = h[i]; h[i] = h[big]; h[big] = t;
                swaps++;
                i = big;
            }
        }
        return swaps;
    }
    // One-by-one build: each new item is sifted up towards the root
    static long buildByInsert(int[] h, int n) {
        long swaps = 0;
        for (int size = 1; size < n; size++) {
            int i = size;
            while (i > 0 && h[(i - 1) / 2] < h[i]) {   // up to log n levels per item
                int p = (i - 1) / 2;
                int t = h[i]; h[i] = h[p]; h[p] = t;
                swaps++;
                i = p;
            }
        }
        return swaps;
    }
