import java.util.ArrayDeque;
public class Main {
    // Recursive version: one call-stack frame per number, so depth = n
    static long sumRecursive(int n) {
        if (n == 0) return 0;
        return n + sumRecursive(n - 1);
    }
    // Same work with our own stack, which lives on the heap and can grow large
    static long sumWithStack(int n) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        for (int i = n; i >= 1; i--) stack.push(i);   // "calls" waiting to run
        long total = 0;
        while (!stack.isEmpty()) total += stack.pop();
        return total;
    }
    public static void main(String[] args) {
        // Small n: recursion is fine (depth 10)
        System.out.println("recursive sum 1..10 = " + sumRecursive(10));
        // Large n: depth 1,000,000 would overflow the call stack, the loop does not
        System.out.println("explicit-stack sum 1..1000000 = " + sumWithStack(1000000));
        // Time: O(n) for both. Space: O(n) call stack vs O(n) heap.
    }
}

