            System.out.println("n=" + n + " levels=" + log
                + " | 2T(n/2)+n = " + twoHalves(n) + " (n*log2 n = " + (n * log) + ")"
                + " | T(n/2)+n = " + oneHalf(n) + " (2n-1 = " + (2 * n - 1) + ")");
