public class Main {
    static long cmp;                       // comparisons made by the sort being measured
    static void insertionSort(int[] a) {
        for (int i = 1; i < a.length; i++) {
            int key = a[i], j = i - 1;
            while (j >= 0) {
                cmp++;
                if (a[j] <= key) break;    // already in place: stop after one comparison
                a[j + 1] = a[j];
                j--;
            }
            a[j + 1] = key;
        }
    }
    static void mergeSort(int[] a, int lo, int hi) {   // sorts a[lo..hi)
        if (hi - lo < 2) return;
        int mid = (lo + hi) / 2;
        mergeSort(a, lo, mid);
        mergeSort(a, mid, hi);
        int[] tmp = new int[hi - lo];      // extra memory on every merge
        int i = lo, j = mid, k = 0;
        while (i < mid && j < hi) {
            cmp++;
            if (a[i] <= a[j]) tmp[k++] = a[i++]; else tmp[k++] = a[j++];
        }
        while (i < mid) tmp[k++] = a[i++];
        while (j < hi) tmp[k++] = a[j++];
        for (k = 0; k < tmp.length; k++) a[lo + k] = tmp[k];
    }
    static void measure(String label, int[] data) {
        int[] x = data.clone(), y = data.clone();
        cmp = 0; insertionSort(x); long ins = cmp;
        cmp = 0; mergeSort(y, 0, y.length); long mer = cmp;
        System.out.println(label + ": insertion=" + ins + " merge=" + mer + " comparisons");
    }
    public static void main(String[] args) {
        // Small and nearly sorted: the "worse" Big-O does less work
        measure("n=8 nearly sorted [1,2,4,3,5,6,8,7]", new int[]{1, 2, 4, 3, 5, 6, 8, 7});
