import java.util.HashMap;
public class Main {
    public static void main(String[] args) {
        int users = 1000, orders = 5000;
        int[] owner = new int[orders];
        for (int i = 0; i < orders; i++) owner[i] = (i * 7) % users;   // order i belongs to this user
        System.out.println("users=" + users + " orders=" + orders);
        // Slow: for each user, scan every order -> users * orders checks
        long slowWork = 0;
        int[] countSlow = new int[users];
        for (int u = 0; u < users; u++)
            for (int i = 0; i < orders; i++) {
                slowWork++;
                if (owner[i] == u) countSlow[u]++;
            }
        // Fast: one pass over the orders, grouping by user in a hash map
        long fastWork = 0;
        HashMap<Integer, Integer> countFast = new HashMap<>();
        for (int i = 0; i < orders; i++) {
            fastWork++;
            countFast.put(owner[i], countFast.getOrDefault(owner[i], 0) + 1);
        }
        boolean same = true;
        for (int u = 0; u < users; u++)
            if (countSlow[u] != countFast.getOrDefault(u, 0)) same = false;
        System.out.println("nested loops: " + slowWork + " checks");
        System.out.println("hash map:     " + fastWork + " checks");
        System.out.println("orders of user 0 = " + countSlow[0] + ", same answers = " + (same ? "yes" : "no"));
        // Time: O(users * orders) vs O(users + orders). Space: O(users) for the map.
    }
}

